import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load and apply background image texture
  if (config.imageUrl) {
    const texture = ctx.textureLoader.load(config.imageUrl);
    texture.colorSpace = THREE.SRGBColorSpace;

    // Plane dimensions based on 512x320 image aspect ratio
    const width = 2.0;
    const height = 1.25;
    const geometry = new THREE.PlaneGeometry(width, height);

    const material = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
    });

    const plane = new THREE.Mesh(geometry, material);
    group.add(plane);
  }

  // Render text content using MSDF font atlas
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh(config.textContent, {
      fontSize: 0.2,
      font: 'Lora',
      weight: 400,
      color: new THREE.Color(0x16161d),
      align: 'center',
    });

    if (textMesh) {
      group.add(textMesh);
    }
  }

  // Apply scene position, rotation, and scale
  if (config.scenePosition) {
    const sp = config.scenePosition;

    if (sp.x !== undefined || sp.y !== undefined || sp.z !== undefined) {
      group.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);
    }

    if (sp.rotationXYZ && sp.rotationXYZ.length >= 3) {
      group.rotation.order = 'XYZ';
      group.rotation.x = sp.rotationXYZ[0] ?? 0;
      group.rotation.y = sp.rotationXYZ[1] ?? 0;
      group.rotation.z = sp.rotationXYZ[2] ?? 0;
    }

    if (sp.scaleXYZ && sp.scaleXYZ.length >= 3) {
      group.scale.x = sp.scaleXYZ[0] ?? 1;
      group.scale.y = sp.scaleXYZ[1] ?? 1;
      group.scale.z = sp.scaleXYZ[2] ?? 1;
    }
  }

  // Cleanup function - dispose all resources and kill GSAP timelines
  group.userData.cleanup = () => {
    // Kill any GSAP animations
    gsap.killTweensOf(group);

    // Dispose all geometries and materials
    group.traverse(node => {
      if (node instanceof THREE.Mesh) {
        if (node.geometry) node.geometry.dispose();
        if (node.material) {
          const materials = Array.isArray(node.material) ? node.material : [node.material];
          materials.forEach(mat => mat.dispose());
        }
      }
    });
  };

  // Event handlers container
  group.userData.handlers = {};

  return group;
}
